/// Flat list combining every department catalog (mirrors ALL_COURSES).
const List<Course> ALL_COURSES = <Course>[
  ...CSE_COURSES,
  ...CSE_AIML_COURSES,
  ...IT_COURSES,
  ...ECE_COURSES,
  ...EEE_COURSES,
  ...MECH_COURSES,
  ...CIVIL_COURSES,
  ...BTECH_AIDS_COURSES,
  ...CSBS_COURSES,
];

Course? getCourseByCode(String code) {
  for (final c in ALL_COURSES) {
    if (c.code == code) return c;
  }
  return null;
}

String getCourseNameByCode(String code) {
  return getCourseByCode(code)?.name ?? code;
}

